#include <bits/stdc++.h>
using namespace std;

static const long long mod = 998244353;

long long modPow(long long a, long long e) {
    a %= mod;
    long long res = 1;
    while (e > 0) {
        if (e & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        e >>= 1;
    }
    return res;
}

vector<long long> fac, invfac;

long long nck(long long n, long long k) {
    return fac[(int)n] * invfac[(int)k] % mod * invfac[(int)(n - k)] % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    fac.resize(n + 1);
    invfac.resize(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; i++) {
        fac[i] = (i * fac[i - 1]) % mod;
    }
    invfac[0] = 1;
    for (int i = 1; i <= n; i++) {
        invfac[i] = (invfac[i - 1] * modPow(i, mod - 2)) % mod;
    }
    long long m = n - k;
    long long posans = 0, negans = 0;
    for (int i = 0; i <= m; i++) {
        long long term = (modPow(m - i, n) * nck(m, i)) % mod;
        if (i % 2 == 0) {
            posans = (posans + term) % mod;
        } else {
            negans = (negans + term) % mod;
        }
    }
    long long ans = (posans - negans + 2 * mod) % mod;
    ans = (ans * nck(n, m)) % mod;
    if (m != n) {
        ans = (ans * 2) % mod;
    }
    cout << ans << "\n";
    return 0;
}

